switch_rqbit() {
  local theme_dir="${XDG_CONFIG_HOME:-$HOME/.config}/rqbit-desktop"
  local theme_file="$theme_dir/quickshell.css"
  local scheme="dark"
  case "${THEME:-}" in pastelglow|gruvbox-light) scheme="light" ;; esac
  mkdir -p "$theme_dir"

  local theme_tmp
  theme_tmp="$(mktemp "${theme_file}.XXXXXX")" || return 1
  # rqbit 9 uses these semantic variables in both its light and dark UI.
  cat > "$theme_tmp" << EOF
/* Auto-generated by switch-theme.sh */
:root, body, .dark {
  color-scheme: $scheme !important;
  --color-surface: ${C[base]} !important;
  --color-surface-raised: ${C[surface0]} !important;
  --color-surface-sunken: ${C[mantle]} !important;
  --color-text: ${C[text]} !important;
  --color-secondary: ${C[subtext0]} !important;
  --color-tertiary: ${C[overlay1]} !important;
  --color-border: ${C[surface1]} !important;
  --color-border-strong: ${C[surface2]} !important;
  --color-divider: ${C[surface1]} !important;
  --color-divider-strong: ${C[surface2]} !important;
  --border-color-primary: ${C[accent]} !important;
  --border-color-divider: ${C[surface1]} !important;
  --border-color-divider-strong: ${C[surface2]} !important;
  --color-primary: ${C[accent]} !important;
  --color-primary-hover: ${C[mauve]} !important;
  --color-primary-bg: ${C[accent]} !important;
  --color-primary-bg-hover: ${C[mauve]} !important;
  --color-success: ${C[green]} !important;
  --color-success-bg: ${C[green]} !important;
  --color-warning: ${C[yellow]} !important;
  --color-warning-bg: ${C[yellow]} !important;
  --color-error: ${C[red]} !important;
  --color-error-bg: ${C[red]} !important;
}
body { background-color: ${C[base]} !important; color: ${C[text]} !important; }
input, select, textarea { accent-color: ${C[accent]}; }
button.bg-primary-bg, button.hover\\:bg-primary:hover {
  color: ${C[base]} !important;
}
button.bg-error-bg { color: ${C[base]} !important; }
button.hover\\:bg-red-600:hover { background-color: ${C[maroon]} !important; }
EOF
  mv "$theme_tmp" "$theme_file"
}
